      "term": {
        "text": "for each loop",
        "refs": ["Q0000"]
      },
      "definition_text": {
        "text": "A loop construct in Java used to iterate over arrays or collections without needing an explicit index or counter.",
        "refs": ["Q0000"]
      },
      "context": null
    }
  ],
  "examples": [],
  "explanations": [
    {
      "topic": {
        "text": "limitations of the for each loop",
        "refs": ["Q0004", "Q0005"]
      },
      "explanation_text": {
        "text": "The for each loop is always forward only and does not provide access to the index of each item; only the value of each item is available.",
        "refs": ["Q0004", "Q0005"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "danger of while true without a break",
        "refs": ["Q0000"]
      },
      "explanation_text": {
        "text": "Using a while true loop without a break statement creates an infinite loop that never terminates, which can be dangerous in terms of memory consumption.",
        "refs": ["Q0000"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "In a for each loop, the loop variable holds the value of each item in the array during each iteration.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "When validating user input, an infinite loop (while true) can be used to repeatedly ask the same question until a valid value is entered.",
        "refs": ["Q0009"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [
    {
      "procedure_name": {
        "text": "Validate user input with an infinite loop",
        "refs": ["Q0008", "Q0009"]
      },
      "steps": [
        {
          "text": "Wrap the input prompt inside a while true loop.",
          "refs": ["Q0009"]
        },
        {
          "text": "Read the user input.",
          "refs": ["Q0009"]
        },
        {
          "text": "If the input is within the valid range, break out of the loop; otherwise, display an error message and repeat.",
          "refs": ["Q0009"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "Use an infinite loop to repeatedly ask for input until a valid value is entered, breaking out when the condition is satisfied.",
        "refs": ["Q0008", "Q0009"]
      }
    }
  ],
